"use server";
import { randomUUID } from "node:crypto"; import { and, eq, inArray, or } from "drizzle-orm"; import { revalidatePath } from "next/cache"; import { headers } from "next/headers"; import { redirect } from "next/navigation"; import { z } from "zod"; import { db } from "@/db/client"; import { categories, comboItems, combos, customers, galleryImages, galleryItems, homepageSections, inquiries, inquiryImages, mediaAssets, orders, productComplementRecommendations, productImages, products, productVariants, siteSettings } from "@/db/schema"; import { clearAdminSession, requireAdmin } from "@/lib/admin-auth"; import { homepageSectionKeys } from "@/lib/homepage";
import { services } from "@/db/schema";
import { deletePrivateBlob, deletePublicBlob, uploadPublicBlob } from "@/lib/blob";
import { assertTransition, inquiryTransitions, orderTransitions } from "@/lib/workflow";
import { productDescriptionText, sanitizeProductDescription } from "@/lib/product-description";
