const text=(form:FormData,key:string)=>String(form.get(key)??"").trim(); const integer=(form:FormData,key:string)=>Number.parseInt(text(form,key),10)||0;
async function assertSafeUpload(file:File,allowed:readonly string[],maxBytes:number,message:string){const bytes=new Uint8Array(await file.arrayBuffer());if(!isValidUploadedFile(bytes,file.type,file.size,allowed,maxBytes))throw new Error(message);}
type AssetRecord={id:string;provider:string;providerId:string};
async function removeAsset(asset:AssetRecord){const references=await Promise.all([db.select({id:productImages.id}).from(productImages).where(eq(productImages.mediaAssetId,asset.id)).limit(1),db.select({id:galleryImages.id}).from(galleryImages).where(eq(galleryImages.mediaAssetId,asset.id)).limit(1),db.select({id:inquiryImages.id}).from(inquiryImages).where(eq(inquiryImages.mediaAssetId,asset.id)).limit(1),db.select({id:orders.id}).from(orders).where(eq(orders.paymentProofAssetId,asset.id)).limit(1),db.select({id:services.id}).from(services).where(eq(services.imageId,asset.id)).limit(1)]);if(references.some(rows=>rows.length))return;const[deleted]=await db.delete(mediaAssets).where(eq(mediaAssets.id,asset.id)).returning({id:mediaAssets.id});if(!deleted)return;if(asset.provider==="neon-object-storage-private")await deletePrivateBlob(asset.providerId);else if(asset.provider==="neon-object-storage"||asset.provider==="object-storage")await deletePublicBlob(asset.providerId);}
function homepageImageUrls(content:unknown){const images=(content as {images?:unknown}|null)?.images;return Array.isArray(images)?images.filter((image):image is string=>typeof image==="string"&&image.startsWith("/uploads/homepage/")):[]}
async function removeUnusedHomepageImages(urls:string[]){const candidates=[...new Set(urls.filter(url=>url.startsWith("/uploads/homepage/")))];if(!candidates.length)return;const[sections,settings]=await Promise.all([db.select({content:homepageSections.content}).from(homepageSections),db.select({value:siteSettings.value}).from(siteSettings)]);const inUse=new Set(sections.flatMap(section=>homepageImageUrls(section.content)));const settingsJson=JSON.stringify(settings.map(setting=>setting.value));const assets=await db.select({id:mediaAssets.id,provider:mediaAssets.provider,providerId:mediaAssets.providerId,url:mediaAssets.url}).from(mediaAssets).where(inArray(mediaAssets.url,candidates));await Promise.allSettled(assets.filter(asset=>!inUse.has(asset.url)&&!settingsJson.includes(asset.url)).map(removeAsset));}
async function editIdFromRequest(){const referer=(await headers()).get("referer");if(!referer)return "";try{return new URL(referer).searchParams.get("edit")??""}catch{return ""}}
export async function logoutAdmin(){await requireAdmin();await clearAdminSession();redirect("/acceso-admin")}
export async function saveProduct(form:FormData){
  await requireAdmin();
  const file=form.get("imageFile"); const imageFile=file instanceof File&&file.size>0?file:null;
  if(imageFile)await assertSafeUpload(imageFile,["image/jpeg","image/png","image/webp"],8_000_000,"Usa una imagen JPG, PNG o WebP válida de máximo 8 MB.");
  const schema=z.object({id:z.string().optional(),name:z.string().min(2).max(140),slug:z.string().regex(/^[a-z0-9-]+$/),type:z.enum(["floral","complement","personalized"]),categoryId:z.string().uuid().optional().or(z.literal("")),basePrice:z.number().int().min(0),status:z.enum(["draft","active","archived"]),description:z.string().max(20_000)});
  const value=schema.parse({id:text(form,"id")||undefined,name:text(form,"name"),slug:text(form,"slug"),type:text(form,"type"),categoryId:text(form,"categoryId"),basePrice:integer(form,"basePrice"),status:text(form,"status"),description:text(form,"description")});
  const description=sanitizeProductDescription(value.description);const shortDescription=productDescriptionText(description).slice(0,500)||null;
  const existing=await db.select({id:products.id}).from(products).where(eq(products.slug,value.slug)).limit(1);
  if(existing[0]&&existing[0].id!==value.id)throw new Error("[field:slug] Ya existe un producto con ese identificador URL.");
  let productId=value.id;
  if(productId)await db.update(products).set({name:value.name,slug:value.slug,type:value.type,categoryId:value.categoryId||null,basePrice:value.basePrice,status:value.status,featured:form.get("featured")==="on",shortDescription,description:description||null,updatedAt:new Date()}).where(eq(products.id,productId));
  else{const[row]=await db.insert(products).values({name:value.name,slug:value.slug,type:value.type,categoryId:value.categoryId||null,basePrice:value.basePrice,status:value.status,featured:form.get("featured")==="on",shortDescription,description:description||null,customizable:value.type==="personalized"}).returning();productId=row.id;await db.insert(productVariants).values({productId,name:"Estándar",price:value.basePrice});}
  if(form.get("removeImage")==="on"||imageFile){const currentImages=await db.select({id:productImages.id,assetId:mediaAssets.id,provider:mediaAssets.provider,providerId:mediaAssets.providerId}).from(productImages).innerJoin(mediaAssets,eq(productImages.mediaAssetId,mediaAssets.id)).where(and(eq(productImages.productId,productId),eq(productImages.primary,true)));await db.delete(productImages).where(and(eq(productImages.productId,productId),eq(productImages.primary,true)));await Promise.all(currentImages.map(image=>removeAsset({id:image.assetId,provider:image.provider,providerId:image.providerId})));}
  if(imageFile){const uploaded=await uploadPublicBlob(`products/${productId}-${randomUUID()}.${imageFile.type==="image/png"?"png":imageFile.type==="image/webp"?"webp":"jpg"}`,imageFile);try{const[asset]=await db.insert(mediaAssets).values({provider:"object-storage",providerId:uploaded.pathname,url:uploaded.url,alt:value.name,bytes:imageFile.size,format:imageFile.type.replace("image/",""),visibility:"public"}).returning();await db.insert(productImages).values({productId,mediaAssetId:asset.id,primary:true}).onConflictDoNothing();}catch(error){await deletePublicBlob(uploaded.pathname).catch(()=>undefined);throw error;}}
  revalidatePath("/admin/productos");revalidatePath("/flores");revalidatePath("/");
}
export async function archiveProduct(form:FormData){await requireAdmin();await db.update(products).set({status:"archived",updatedAt:new Date()}).where(eq(products.id,text(form,"id")));revalidatePath("/admin/productos");revalidatePath("/flores")}
export async function deleteArchivedProduct(form:FormData){await requireAdmin();const id=z.string().uuid().parse(text(form,"id"));const[row]=await db.select({status:products.status}).from(products).where(eq(products.id,id)).limit(1);if(!row)throw new Error("El producto ya no existe.");if(row.status!=="archived")throw new Error("Solo puedes eliminar productos archivados.");await db.delete(products).where(eq(products.id,id));revalidatePath("/admin/productos");revalidatePath("/flores")}
export async function saveCategory(form:FormData){await requireAdmin();const id=text(form,"id");const parsed=z.object({name:z.string().trim().min(2,"El nombre debe tener al menos 2 caracteres.").max(100),slug:z.string().regex(/^[a-z0-9-]+$/,"Usa solo letras minúsculas, números y guiones en el identificador URL."),description:z.string().max(500,"La descripción no puede superar 500 caracteres."),sortOrder:z.number().int("El orden debe ser un número entero.").min(0,"El orden no puede ser negativo.")}).safeParse({name:text(form,"name"),slug:text(form,"slug"),description:text(form,"description"),sortOrder:integer(form,"sortOrder")});if(!parsed.success){const issue=parsed.error.issues[0];throw new Error(`[field:${String(issue?.path[0]??"form")}] ${issue?.message??"Revisa los datos de la categoría."}`);}const value=parsed.data;const duplicate=await db.select({id:categories.id}).from(categories).where(eq(categories.slug,value.slug)).limit(1);if(duplicate[0]&&duplicate[0].id!==id)throw new Error("[field:slug] Ya existe una categoría con ese identificador URL.");const sameOrder=await db.select({id:categories.id}).from(categories).where(eq(categories.sortOrder,value.sortOrder));if(sameOrder.some(item=>item.id!==id))throw new Error("[field:sortOrder] Ya existe una categoría con ese orden. Usa otro número.");const values={...value,description:value.description||null,visible:form.get("visible")==="on",updatedAt:new Date()};if(id)await db.update(categories).set(values).where(eq(categories.id,z.string().uuid().parse(id)));else await db.insert(categories).values(values);revalidatePath("/admin/categorias");revalidatePath("/flores")}
export async function createCategoryQuick(form:FormData){await requireAdmin();const value=z.object({name:z.string().trim().min(2).max(100),slug:z.string().regex(/^[a-z0-9-]+$/),description:z.string().max(500),sortOrder:z.number().int().min(0)}).parse({name:text(form,"name"),slug:text(form,"slug"),description:text(form,"description"),sortOrder:integer(form,"sortOrder")});const[existing]=await db.select({id:categories.id}).from(categories).where(eq(categories.slug,value.slug)).limit(1);if(existing)throw new Error("Ya existe una categoría con ese identificador URL.");const[row]=await db.insert(categories).values({...value,description:value.description||null,visible:form.get("visible")!=="false"}).returning({id:categories.id,name:categories.name,slug:categories.slug});revalidatePath("/flores");return row}
export async function archiveCategory(form:FormData){await requireAdmin();const id=z.string().uuid().parse(text(form,"id"));await db.update(categories).set({visible:false,updatedAt:new Date()}).where(eq(categories.id,id));revalidatePath("/admin/categorias");revalidatePath("/flores")}
export async function saveGalleryItem(form:FormData){await requireAdmin();const id=text(form,"id")||await editIdFromRequest();if(id)z.string().uuid().parse(id);const value=z.object({title:z.string().trim().min(2).max(160),slug:z.string().regex(/^[a-z0-9-]+$/),description:z.string().trim().max(2000),alt:z.string().trim().max(240),galleryCategory:z.enum(["flores","bodas","eventos","personalizados"]),sortOrder:z.number().int().min(0)}).parse({title:text(form,"title"),slug:text(form,"slug"),description:text(form,"description"),alt:text(form,"alt"),galleryCategory:text(form,"galleryCategory"),sortOrder:integer(form,"sortOrder")});const imageFiles=form.getAll("imageFiles").filter((file):file is File=>file instanceof File&&file.size>0);for(const file of imageFiles)await assertSafeUpload(file,["image/jpeg","image/png","image/webp"],8_000_000,"Usa imágenes JPG, PNG o WebP válidas de máximo 8 MB cada una.");const current=id?await db.select({id:galleryImages.id,assetId:mediaAssets.id,provider:mediaAssets.provider,providerId:mediaAssets.providerId}).from(galleryImages).innerJoin(mediaAssets,eq(galleryImages.mediaAssetId,mediaAssets.id)).where(eq(galleryImages.galleryItemId,id)).orderBy(galleryImages.sortOrder):[];let imageOrder:Array<{id?:string;newIndex?:number}>=[];try{const parsed=JSON.parse(text(form,"galleryImageOrder")||"[]");if(Array.isArray(parsed))imageOrder=parsed.filter(item=>item&&((typeof item.id==="string")||(Number.isInteger(item.newIndex)&&item.newIndex>=0)));}catch{throw new Error("El orden de las imágenes no es válido.");}if(!imageOrder.length)imageOrder=[...current.map(image=>({id:image.id})),...imageFiles.map((_,newIndex)=>({newIndex}))];const currentIds=new Set(current.map(image=>image.id));const retainedIds=imageOrder.flatMap(item=>item.id?[item.id]:[]);if(retainedIds.some(item=>!currentIds.has(item))||new Set(retainedIds).size!==retainedIds.length)throw new Error("La selección de imágenes no es válida.");const newIndexes=imageOrder.flatMap(item=>Number.isInteger(item.newIndex)?[item.newIndex!]:[]);if(newIndexes.length!==imageFiles.length||new Set(newIndexes).size!==newIndexes.length||newIndexes.some(index=>index<0||index>=imageFiles.length))throw new Error("El orden de las imágenes nuevas no es válido.");const duplicate=await db.select({id:galleryItems.id}).from(galleryItems).where(eq(galleryItems.slug,value.slug)).limit(1);if(duplicate[0]&&duplicate[0].id!==id)throw new Error("[field:slug] Ya existe una publicación con ese identificador URL.");const values={title:value.title,slug:value.slug,description:value.description||null,galleryCategory:value.galleryCategory,featured:form.get("featured")==="on",visible:form.get("visible")==="on",sortOrder:value.sortOrder,updatedAt:new Date()};let galleryId=id;await db.transaction(async tx=>{if(values.featured)await tx.update(galleryItems).set({featured:false,updatedAt:new Date()}).where(eq(galleryItems.featured,true));if(galleryId){const[updated]=await tx.update(galleryItems).set(values).where(eq(galleryItems.id,galleryId)).returning({id:galleryItems.id});if(!updated)throw new Error("La publicación ya no existe.");}else{const[created]=await tx.insert(galleryItems).values(values).returning({id:galleryItems.id});galleryId=created.id;}});const uploaded:Array<{file:File;extension:string;pathname:string;url:string}>=[];try{for(const file of imageFiles){const extension=file.type==="image/png"?"png":file.type==="image/webp"?"webp":"jpg";const upload=await uploadPublicBlob(`gallery/${galleryId}-${randomUUID()}.${extension}`,file);uploaded.push({file,extension,pathname:upload.pathname,url:upload.url});}const currentById=new Map(current.map(image=>[image.id,image]));await db.transaction(async tx=>{await tx.delete(galleryImages).where(eq(galleryImages.galleryItemId,galleryId));const links:Array<{galleryItemId:string;mediaAssetId:string;sortOrder:number}>=[];for(let sortOrder=0;sortOrder<imageOrder.length;sortOrder++){const item=imageOrder[sortOrder];if(item.id){const image=currentById.get(item.id)!;await tx.update(mediaAssets).set({alt:value.alt||value.title}).where(eq(mediaAssets.id,image.assetId));links.push({galleryItemId:galleryId,mediaAssetId:image.assetId,sortOrder});continue;}const itemUpload=uploaded[item.newIndex!];const[asset]=await tx.insert(mediaAssets).values({provider:"object-storage",providerId:itemUpload.pathname,url:itemUpload.url,alt:value.alt||value.title,bytes:itemUpload.file.size,format:itemUpload.extension,visibility:"public"}).returning({id:mediaAssets.id});links.push({galleryItemId:galleryId,mediaAssetId:asset.id,sortOrder});}if(links.length)await tx.insert(galleryImages).values(links);});const retained=new Set(retainedIds);await Promise.all(current.filter(image=>!retained.has(image.id)).map(image=>removeAsset({id:image.assetId,provider:image.provider,providerId:image.providerId})));}catch(error){await Promise.all(uploaded.map(item=>deletePublicBlob(item.pathname).catch(()=>undefined)));throw error;}revalidatePath("/admin/galeria");revalidatePath("/gallery")}
export async function updateInquiry(form:FormData){await requireAdmin();const id=z.string().uuid().parse(text(form,"id"));const status=z.enum(["new","reviewing","quoting","quoted","approved","rejected","completed"]).parse(text(form,"status"));const[current]=await db.select({status:inquiries.status}).from(inquiries).where(eq(inquiries.id,id)).limit(1);if(!current)throw new Error("Solicitud no encontrada.");assertTransition(inquiryTransitions,current.status,status,"solicitud");await db.update(inquiries).set({status,internalNotes:text(form,"internalNotes"),updatedAt:new Date()}).where(and(eq(inquiries.id,id),eq(inquiries.status,current.status)));revalidatePath("/admin/solicitudes")}
export async function saveOrder(form:FormData){await requireAdmin();const id=text(form,"id");const status=z.enum(["draft","pending","confirmed","preparing","ready","delivered","cancelled"]).parse(text(form,"status"));if(id){const[current]=await db.select({status:orders.status,reference:orders.reference,fulfillment:orders.fulfillment,customerName:customers.name,customerEmail:customers.email}).from(orders).innerJoin(customers,eq(orders.customerId,customers.id)).where(eq(orders.id,id)).limit(1);if(!current)throw new Error("Pedido no encontrado.");assertTransition(orderTransitions,current.status,status,"pedido");const[updated]=await db.update(orders).set({status,updatedAt:new Date()}).where(and(eq(orders.id,id),eq(orders.status,current.status))).returning({id:orders.id});if(!updated)throw new Error("El pedido fue actualizado por otra sesión. Actualiza la página e inténtalo de nuevo.");const email=status==="preparing"&&current.status!=="preparing"?await sendOrderPreparingEmail({reference:current.reference,name:current.customerName,email:current.customerEmail??undefined,fulfillment:current.fulfillment}).catch(error=>{console.error("order_preparing_email_failed",{reference:current.reference,error});return{sent:false as const}}):undefined;revalidatePath("/admin/pedidos");return{changed:true,emailSent:email?.sent};}const subtotal=integer(form,"subtotal"),deliveryFee=integer(form,"deliveryFee"),deposit=integer(form,"deposit"),total=subtotal+deliveryFee;await db.insert(orders).values({reference:`PED-${randomUUID().replaceAll("-","").slice(0,12).toUpperCase()}`,trackingToken:randomUUID().replaceAll("-",""),customerId:text(form,"customerId"),inquiryId:text(form,"inquiryId")||null,fulfillment:text(form,"fulfillment")==="delivery"?"delivery":"pickup",deliveryAddress:text(form,"deliveryAddress")||null,subtotal,deliveryFee,total,deposit,balance:total-deposit,status});revalidatePath("/admin/pedidos");return{changed:true,emailSent:undefined}}
export async function reviewOrderPayment(form:FormData){await requireAdmin();const id=z.string().uuid().parse(text(form,"id"));const paymentStatus=z.enum(["paid","failed"]).parse(text(form,"paymentStatus"));const result=await reviewOrderPaymentById(id,paymentStatus);if(!result.changed)return{changed:false,emailSent:false};const email=await sendPaymentReviewEmail({reference:result.reference,name:result.customerName,email:result.customerEmail,paymentStatus:result.paymentStatus,balance:result.balance}).catch(error=>{console.error("payment_review_email_failed",{reference:result.reference,error});return{sent:false as const}});revalidatePath("/admin/pedidos");return{changed:true,emailSent:email.sent}}
export async function resendPaymentReviewEmail(form:FormData){await requireAdmin();const id=z.string().uuid().parse(text(form,"id"));const[order]=await db.select({reference:orders.reference,paymentStatus:orders.paymentStatus,balance:orders.balance,customerName:customers.name,customerEmail:customers.email}).from(orders).innerJoin(customers,eq(customers.id,orders.customerId)).where(eq(orders.id,id)).limit(1);if(!order)throw new Error("Pedido no encontrado.");if(order.paymentStatus!=="paid"&&order.paymentStatus!=="failed")throw new Error("Este pedido todavía no tiene una resolución de pago para notificar.");const email=await sendPaymentReviewEmail({reference:order.reference,name:order.customerName,email:order.customerEmail??undefined,paymentStatus:order.paymentStatus,balance:order.balance});return{emailSent:email.sent}}
export async function saveHomepageSection(form:FormData){await requireAdmin();const id=text(form,"id");const key=z.enum(homepageSectionKeys).parse(text(form,"key"));const images=form.getAll("images").map(String).filter(Boolean);const imageLabels=form.getAll("imageLabels").map(String).map(label=>label.trim()).filter(Boolean);const[previous]=await db.select({content:homepageSections.content}).from(homepageSections).where(eq(homepageSections.key,key)).limit(1);const content={titleEs:text(form,"titleEs"),titleEn:text(form,"titleEn"),subtitleEs:text(form,"subtitleEs"),subtitleEn:text(form,"subtitleEn"),images,imageLabels};const values={key,content,visible:form.get("visible")==="on",sortOrder:integer(form,"sortOrder"),startsAt:null,endsAt:null,updatedAt:new Date()};if(id)await db.update(homepageSections).set(values).where(eq(homepageSections.id,id));else await db.insert(homepageSections).values(values).onConflictDoUpdate({target:homepageSections.key,set:values});await removeUnusedHomepageImages(homepageImageUrls(previous?.content).filter(url=>!images.includes(url)));revalidatePath("/admin/inicio");revalidatePath("/")}
