async function persistBrandFile(form:FormData,key:string,folder:string,allowed:string[],maxBytes:number,current:string){const file=form.get(key);if(!(file instanceof File)||file.size===0)return current;if(file.size>maxBytes||!allowed.includes(file.type))throw new Error(`El archivo de ${key} no tiene un formato o tamaño permitido.`);const extension=({"image/jpeg":"jpg","image/png":"png","image/webp":"webp","image/svg+xml":"svg","image/x-icon":"ico","image/vnd.microsoft.icon":"ico","video/mp4":"mp4","video/webm":"webm"} as Record<string,string>)[file.type];const blob=await uploadPublicBlob(`branding/${folder}-${randomUUID()}.${extension}`,file);await db.insert(mediaAssets).values({provider:"neon-object-storage",providerId:blob.pathname,url:blob.url,bytes:file.size,format:extension,alt:text(form,key.includes("hero")?"heroImageAltEs":"logoAltEs")||file.name,visibility:"public"});return blob.url;}
