function brandingSaveErrorMessage(error:unknown){const storageError=error as {name?:string;Code?:string};if(storageError.name==="SignatureDoesNotMatch"||storageError.Code==="SignatureDoesNotMatch")return "No se pudo subir el archivo. La conexión con el almacenamiento de Neon necesita actualizarse.";return "No se pudieron publicar los cambios. Inténtalo nuevamente.";}
export async function saveBrandingSettings(form:FormData):Promise<BrandingSaveResult>{
  await requireAdmin();
  try{
    const selected=(key:string)=>{const file=form.get(key);return file instanceof File&&file.size>0};
    if(selected("heroVideo")&&text(form,"heroVideoUrl"))return {ok:false,message:"Elige solo una fuente para el video: URL o archivo."};
    if(selected("heroImage")&&text(form,"heroImageUrl"))return {ok:false,message:"Elige solo una fuente para la imagen: URL o archivo."};
    const currentRow=await db.select({value:siteSettings.value}).from(siteSettings).where(eq(siteSettings.key,"branding")).limit(1);
    const current=(currentRow[0]?.value??{}) as Record<string,unknown>;
    const base={logoUrl:text(form,"logoUrl")||String(current.logoUrl??"/orosblooms-logo.png"),faviconUrl:text(form,"faviconUrl")||String(current.faviconUrl??"/orosblooms-favicon.png"),heroImageUrl:text(form,"heroImageUrl")||String(current.heroImageUrl??"/home-hero.webp"),heroVideoUrl:text(form,"heroVideoUrl")||String(current.heroVideoUrl??"/videos/hero-orosblooms.mp4")};
    const [logoUrl,faviconUrl,heroImageUrl,heroVideoUrl]=await Promise.all([
      persistBrandFile(form,"logo","logo",["image/jpeg","image/png","image/webp","image/svg+xml"],8_000_000,base.logoUrl),
      persistBrandFile(form,"favicon","favicon",["image/png","image/x-icon","image/vnd.microsoft.icon","image/svg+xml"],2_000_000,base.faviconUrl),
      persistBrandFile(form,"heroImage","hero",["image/jpeg","image/png","image/webp"],12_000_000,base.heroImageUrl),
      persistBrandFile(form,"heroVideo","hero-video",["video/mp4","video/webm"],40_000_000,base.heroVideoUrl),
    ]);
    const value=z.object({brandName:z.string().min(2).max(80),logoAltEs:z.string().min(2).max(180),logoAltEn:z.string().min(2).max(180),heroImageAltEs:z.string().min(2).max(240),heroImageAltEn:z.string().min(2).max(240),heroMediaMode:z.enum(["image","image-video"]),backgroundColor:colorSchema,foregroundColor:colorSchema,primaryColor:colorSchema,accentColor:colorSchema,softAccentColor:colorSchema}).parse({brandName:text(form,"brandName"),logoAltEs:text(form,"logoAltEs"),logoAltEn:text(form,"logoAltEn"),heroImageAltEs:text(form,"heroImageAltEs"),heroImageAltEn:text(form,"heroImageAltEn"),heroMediaMode:text(form,"heroMediaMode"),backgroundColor:normalizeColor(text(form,"backgroundColor")),foregroundColor:normalizeColor(text(form,"foregroundColor")),primaryColor:normalizeColor(text(form,"primaryColor")),accentColor:normalizeColor(text(form,"accentColor")),softAccentColor:normalizeColor(text(form,"softAccentColor"))});
    const nextUrls=[logoUrl,faviconUrl,heroImageUrl,heroVideoUrl];
    await db.insert(siteSettings).values({key:"branding",value:{...value,logoUrl,faviconUrl,heroImageUrl,heroVideoUrl}}).onConflictDoUpdate({target:siteSettings.key,set:{value:{...value,logoUrl,faviconUrl,heroImageUrl,heroVideoUrl},updatedAt:new Date()}});
    const replaced=[current.logoUrl,current.faviconUrl,current.heroImageUrl,current.heroVideoUrl].map(item=>String(item??"")).filter(url=>url.startsWith("/uploads/")&&!nextUrls.includes(url));
    if(replaced.length){const assets=await db.select({id:mediaAssets.id,provider:mediaAssets.provider,providerId:mediaAssets.providerId}).from(mediaAssets).where(inArray(mediaAssets.url,replaced));await Promise.allSettled(assets.map(removeAsset));}
    revalidatePath("/","layout");
    revalidatePath("/admin/identidad");
    return {ok:true};
  }catch(error){
    console.error("branding_settings_save_failed",error);
    return {ok:false,message:brandingSaveErrorMessage(error)};
  }
}
